import Foundation

/// JVM entry points for graph artifacts generated by Metro.
enum JVMMetro: String {
    case createGraph
    case createGraphFactory

    static let package = "dev/zacsweers/metro/"
    static let sourcePackage = "dev.zacsweers.metro"
    static let annotationPrefix = "L" + package
    static let facade = package + "CreateGraphKt"
    static let graph = "L" + package + "DependencyGraph;"
    static let factory = "L" + package + "DependencyGraph$Factory;"
    static let provides = "L" + package + "Provides;"
    static let inject = "L" + package + "Inject;"
    static let singleIn = "L" + package + "SingleIn;"
    static let qualifier = "L" + package + "Qualifier;"
    static let contributesTo = "L" + package + "ContributesTo;"
    static let contributesBinding = "L" + package + "ContributesBinding;"
    static let contributesIntoSet = "L" + package + "ContributesIntoSet;"
    static let binds = "L" + package + "Binds;"
    static let intoSet = "L" + package + "IntoSet;"
    static let graphExtension = "L" + package + "GraphExtension;"
    static let extensionFactory = "L" + package + "GraphExtension$Factory;"
    static let contribution = "L" + package + "internal/MetroContribution;"
    static let origin = "L" + package + "Origin;"
    static let implementation = "L" + package + "internal/MetroImplMarker;"
    static let provider = "L" + package + "internal/CallableMetadata;"
    static let invoke = "L" + package + "internal/GraphFactoryInvokeFunctionMarker;"
    static let annotationDescriptors: Set<String> = [
        graph, factory, implementation, provider, invoke, provides, inject, singleIn, qualifier,
        contributesTo, contributesBinding, contributesIntoSet, binds, intoSet, graphExtension, extensionFactory,
        contribution, "L" + package + "BindingContainer;", origin,
    ]

    static let sourcePath = "<kswiftk-jvm-import>/metro-intrinsics.kt"
    static let source = """
    package dev.zacsweers.metro

    inline fun <reified T : Any> createGraph(): T = null!!
    inline fun <reified T : Any> createGraphFactory(): T = null!!
    """

    static func hidesFromSource(_ info: JVMClassInfo) -> Bool {
        info.annotations.contains { $0.descriptor == implementation || $0.descriptor == provider }
    }
}

extension JVMFunctionBuilder {
    func importedMetroCall(_ binding: CallBinding, id: ExprID) throws -> JVMIntrinsicResult? {
        guard let imports = context.jvmImports,
              let declarations = imports.metroDeclarationsFile,
              let symbol = program.sema.symbols.symbol(binding.chosenCallee),
              symbol.declSite?.start.file == declarations,
              let entry = JVMMetro(rawValue: context.interner.resolve(symbol.name))
        else { return nil }

        let missingArtifact = "Metro \(entry.rawValue) requires a concrete type and its Metro-generated JVM artifact on the classpath."
        guard let type = binding.substitutedTypeArguments.first.map({ program.specialized($0) }),
              case let .classType(nominal) = program.sema.types.kind(of: type) else {
            throw fail(missingArtifact, id)
        }
        let name = try program.className(nominal.classSymbol)
        let resultType = try program.expressionType(id)
        switch entry {
        case .createGraphFactory:
            guard let field = program.metroFactoryFields[nominal.classSymbol] ?? imports.metroFactoryInstance(name) else {
                throw fail(missingArtifact, id)
            }
            let instance = try value(field.type)
            instructions.append(.getStatic(field, instance))
            return JVMIntrinsicResult(value: try convert(instance, to: resultType))
        case .createGraph:
            guard let (field, method) = imports.metroGraphInvoker(name) else { throw fail(missingArtifact, id) }
            let companion = try value(field.type)
            instructions.append(.getStatic(field, companion))
            return JVMIntrinsicResult(value: try jdkCall(
                method.owner, method.name, [], method.result, receiver: companion, resolved: resultType
            ))
        }
    }
}
